        const safeBase = ProjetosController.sanitizeBaseName(file.originalname || 'arquivo');
        cb(null, `${Date.now()}-${safeBase}${ext}`);
      }
    }),
    fileFilter: (_req, file, cb) => {
      const ext = extname(file.originalname || '').toLowerCase();
      if (!ALLOWED_RESEARCH_UPLOAD_EXT.has(ext)) {
        cb(new HttpException('Formato de arquivo nao permitido.', HttpStatus.BAD_REQUEST), false);
        return;
      }
      cb(null, true);
    },
    limits: {
      fileSize: MAX_RESEARCH_UPLOAD_SIZE_BYTES
    }
  })
